ite-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px}.top-user-meta small{font-size:8px;color:#8190a4;text-transform:uppercase;letter-spacing:.08em;margin-top:3px}.top .logout-btn{padding:8px 11px;border-radius:9px;font-size:11px;box-shadow:none}.top .unifco-language-switcher{margin:0 1px}.top .unifco-language-switcher button{padding:5px 8px;font-size:10px}.top-system-dot{width:8px;height:8px;border-radius:50%;background:#22a064;box-shadow:0 0 0 3px rgba(34,160,100,.10);display:inline-block;margin-right:1px}.nav-children .nav-link.nav-secondary{color:#c9d4e4}.nav-children .nav-link.nav-secondary:before{content:'·';color:#6f86a5;margin-right:2px}@media(max-width:760px){.top-user-meta small{display:none}.top-user-meta .user-name{max-width:110px}.top-user-chip{padding-right:6px}.top .logout-btn{padding:8px 9px}.top .unifco-language-switcher button{padding:5px 6px}.top{gap:8px}}html[dir="rtl"] body{direction:rtl}html[dir="rtl"] .main{text-align:right}html[dir="rtl"] table th,html[dir="rtl"] table td{text-align:right}html[dir="rtl"] .side{direction:rtl}html[dir="rtl"] .nav-home,html[dir="rtl"] .nav-link{border-left:0;border-right:3px solid transparent}html[dir="rtl"] .nav-home.active,html[dir="rtl"] .nav-link.active{border-right-color:#ce122d}html[dir="rtl"] .nav-group summary:after{margin-left:0;margin-right:auto;transform:rotate(180deg)}html[dir="rtl"] .nav-group[open] summary:after{transform:rotate(90deg)}html[dir="rtl"] .nav-children{margin-left:0;margin-right:27px;padding-left:0;padding-right:7px;border-left:0;border-right:1px solid #ffffff18}html[dir="rtl"] .side-search:before{left:auto;right:11px}html[dir="rtl"] .side-search input{padding-left:10px;padding-right:33px}html[dir="rtl"] .side-collapse{right:auto;left:-6px}html[dir="rtl"] .top-user-chip{padding-left:6px;padding-right:6px}html[dir="rtl"] .top-system-dot{margin-right:0;margin-left:1px}
</style>
