const R=Object.fromEntries(Object.entries(D).map(([a,b])=>[b,a]));
const PEOPLE=[['HR Dashboard','/hr/dashboard']
@if(auth()->user()?->employee_id),['My HR','/hr/self-service'],['My HR Documents','/hr/self-service/documents']@endif
