const NAV={
'Customers & Service':[['Customers','/crm/customers'],['Customer Onboarding','/workspace/customer-onboarding'],['Contracts','/workspace/contracts'],['Service Requests','/admin/public-requests'],['Customer Portal','/workspace/customer-portal']],
'Maintenance & Field Service':[['Work Orders','/maintenance/work-orders'],['Preventive Maintenance','/workspace/preventive-maintenance'],['Scheduling & Dispatch','/field/operations'],['Technician Mobile','/field/technician'],['Parts Requests / Consumption','/workspace/parts-consumption'],['Maintenance Operations','/maintenance/operations']],
'Assets & EAM':[['Asset Register','/eam/assets'],['Asset 360','/workspace/asset-360'],['Asset Health','/eam/health'],['Meters & Readings','/workspace/meters-readings'],['Reliability','/workspace/reliability'],['Spare Parts / Reorder','/workspace/spare-parts-reorder'],['Maintenance Plans','/workspace/maintenance-plans']],
'Inventory & Warehouses':[['Warehouse Control','/inventory/warehouse-control'],['Stock Balances','/inventory/stock'],['Transfers','/workspace/transfers'],['Bins & Locations','/workspace/bins-locations'],['Receiving','/workspace/receiving'],['Material Issues / Returns','/workspace/material-issues-returns'],['Inventory Movements','/workspace/inventory-movements']],
