'Finance':[['Finance Dashboard','/workspace/finance-dashboard'],['Accounts / Chart of Accounts','/workspace/chart-of-accounts'],['Journals','/finance/journals'],['AR / Receivables','/workspace/receivables'],['AP / Payables','/workspace/payables'],['Payments','/workspace/payments'],['Financial Documents','/workspace/financial-documents']],
