'People':PEOPLE,
'Insights & Intelligence':[['Executive Reporting','/reports/executive'],['Operations Analytics','/workspace/operations-analytics'],['Predictive Analytics','/workspace/predictive-analytics'],['AI Assistant','/field/assistant']],
'Platform':[['Notifications','/platform/notifications'],['Documents','/platform/documents'],['Approvals','/workflow/approvals'],['Audit Trail','/admin/audit']],
'Administration':[['Users','/workspace/users'],['Roles & Permissions','/admin/permissions'],['API Tokens','/admin/api-tokens'],['System Settings','/workspace/system-settings']]
};
function completeNav(){document.querySelectorAll('.side .nav-group').forEach(g=>{const s=g.querySelector('summary');if(!s)return;const key=Object.keys(NAV).find(k=>s.textContent.trim().includes(k));if(!key)return;const box=g.querySelector('.nav-children');if(!box)return;const current=location.pathname.replace(/\/$/,'')||'/';box.innerHTML=NAV[key].map(([label,url])=>{const path=url.split('#')[0];return '<a class="nav-link nav-secondary '+((path!=='/'&&current===path)||(path!=='/'&&current.startsWith(path+'/'))?'active':'')+'" href="'+url+'">'+label+'</a>'}).join('')});}
function translate(m){const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),n=[];while(w.nextNode())n.push(w.currentNode);n.forEach(x=>{const s=x.nodeValue.trim();if(s&&m[s])x.nodeValue=x.nodeValue.replace(s,m[s])});const q=document.getElementById('side-nav-search');if(q)q.placeholder=document.documentElement.dataset.unifcoLang==='ar'?'بحث في القائمة…':'Search menu…'}
function set(l){const c=document.documentElement.dataset.unifcoLang||'en';document.documentElement.dataset.unifcoLang=l;if(c!==l)translate(l==='ar'?D:R);document.documentElement.lang=l;document.documentElement.dir=l==='ar'?'rtl':'ltr';localStorage.setItem('unifco_language',l);document.querySelectorAll('.unifco-language-switcher button').forEach(b=>b.classList.toggle('active',b.dataset.lang===l))}
function mountTopbar(u){const zone=u.parentElement;if(!zone)return;zone.classList.add('top-user-zone');const name=u.textContent.trim(),initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'U';const chip=document.createElement('span');chip.className='top-user-chip';const meta=document.createElement('span');meta.className='top-user-meta';const status=document.createElement('small');status.innerHTML='<span class="top-system-dot"></span> System Online';u.parentNode.insertBefore(chip,u);chip.appendChild(Object.assign(document.createElement('span'),{className:'top-user-avatar',textContent:initials}));meta.appendChild(u);meta.appendChild(status);chip.appendChild(meta)}
function init(){completeNav();const u=document.querySelector('.user-name');if(!u)return;if(!document.querySelector('.unifco-language-switcher')){mountTopbar(u);const x=document.createElement('span');x.className='unifco-language-switcher';x.innerHTML='<button type="button" data-lang="ar">العربية</button><button type="button" data-lang="en">English</button>';const chip=document.querySelector('.top-user-chip')||u;chip.insertAdjacentElement('beforebegin',x);x.addEventListener('click',e=>{const b=e.target.closest('button[data-lang]');if(b)set(b.dataset.lang)});document.documentElement.dataset.unifcoLang='en';x.querySelector('[data-lang="en"]').classList.add('active')}if((localStorage.getItem('unifco_language')||'en')==='ar')set('ar')}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
</script>
